.catalog-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
}

.catalog-layout > ::deep aside {
    width: 25%;
    min-width: 240px;
    max-width: 320px;
    flex-shrink: 0;
}

.catalog-main {
    flex: 1;
    padding: 1.5rem 2rem;
}

.loading-state,
.error-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    text-align: center;
    color: #6b7280;
}

.error-state {
    color: #dc2626;
}

.error-state button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
}

